#!/usr/bin/env bash
set -eo pipefail

ARCHON_BANNER="
========================================================================
   ⚡ ArchonDX: Enterprise Architecture & AI-Code Governance Engine
   Designed & Architected by Subhojeet Ghosh (Lead Architect)
   Version: 1.0.0
========================================================================
"

echo "$ARCHON_BANNER"

USER_HOME="${HOME:-$USERPROFILE}"
TARGET_DIR="${USER_HOME}/.claude/commands"
TARGET_FILE="${TARGET_DIR}/archon.md"

if [ "$1" == "--uninstall" ]; then
  rm -f "${TARGET_FILE}"
  echo "✔ ArchonDX uninstalled successfully."
  exit 0
fi

echo "⚡ Installing / Updating ArchonDX to v1.0.0..."
mkdir -p "${TARGET_DIR}"

cat << 'EOF' > "${TARGET_FILE}.b64"

EOF

tr -d '\r' < "${TARGET_FILE}.b64" | (base64 -d 2>/dev/null || base64 --decode) > "${TARGET_FILE}"
rm -f "${TARGET_FILE}.b64"
chmod 644 "${TARGET_FILE}"

echo "✔ ArchonDX v1.0.0 successfully installed to ${TARGET_FILE}!"
echo ""
echo "👉 How to use:"
echo "   1. Open any Salesforce DX repository in your terminal or VS Code."
echo "   2. Start Claude Code (claude)."
echo "   3. Type '/archon' or '/archon origin/main'."
echo ""
echo "Attribution: ArchonDX Core Engine © 2026 Subhojeet Ghosh."
